{
  "meta": {
    "name": "WeatherReporter",
    "description": "Provides current weather information for a specified location."
  },
  "entities": [
    {
      "name": "Location",
      "fields": [
        {
          "name": "name",
          "type": "string",
          "required": true
        },
        {
          "name": "country",
          "type": "string"
        },
        {
          "name": "region",
          "type": "string"
        }
      ]
    },
    {
      "name": "Weather",
      "fields": [
        {
          "name": "temperature",
          "type": "number"
        },
        {
          "name": "condition",
          "type": "string"
        },
        {
          "name": "humidity",
          "type": "number"
        },
        {
          "name": "windSpeed",
          "type": "number"
        },
        {
          "name": "timestamp",
          "type": "datetime"
        }
      ],
      "relations": [
        {
          "name": "location",
          "kind": "manyToOne",
          "target": "Location",
          "required": true
        }
      ]
    }
  ],
  "roles": [],
  "permissions": [],
  "pages": [
    {
      "name": "WeatherLookup",
      "route": "/weather",
      "type": "custom",
      "access": []
    }
  ],
  "plans": [],
  "businessRules": [],
  "auth": {
    "strategy": "none",
    "requireAuth": false
  }
}
